//! The storage interface: positioned reads and writes, modeled on the POSIX
//! system calls `pread` and `pwrite`. Do not edit this file.
//!
//! Your library does all of its I/O through this trait. The program passes it
//! real files; the tests pass simulated files that are far larger than any disk
//! you have, count every call, and misbehave in the ways the documentation
//! below allows.

use std::fs::File;
use std::io;

#[allow(clippy::len_without_is_empty)]
pub trait Storage {
    /// Reads up to `buf.len()` bytes, starting at byte `offset` of the file, into
    /// `buf`, and returns how many bytes it read. Like `pread`:
    /// - it may read fewer bytes than asked for, even far from the end of the file;
    /// - it returns 0 only at or past the end of the file, or when `buf` is empty;
    /// - an error of kind `io::ErrorKind::Interrupted` means nothing was read and
    ///   the call may simply be repeated; any other error is a real failure.
    fn read_at(&mut self, offset: u64, buf: &mut [u8]) -> io::Result<usize>;

    /// Writes up to `buf.len()` bytes from `buf` at byte `offset` of the file, and
    /// returns how many bytes it wrote. Like `pwrite`: it may write fewer bytes
    /// than asked for, and `Interrupted` means nothing was written. Writing past
    /// the end of the file makes the file longer.
    fn write_at(&mut self, offset: u64, buf: &[u8]) -> io::Result<usize>;

    /// The size of the file in bytes.
    fn len(&mut self) -> io::Result<u64>;
}

impl Storage for File {
    fn read_at(&mut self, offset: u64, buf: &mut [u8]) -> io::Result<usize> {
        #[cfg(unix)]
        return std::os::unix::fs::FileExt::read_at(self, buf, offset);
        #[cfg(windows)]
        return std::os::windows::fs::FileExt::seek_read(self, buf, offset);
    }

    fn write_at(&mut self, offset: u64, buf: &[u8]) -> io::Result<usize> {
        #[cfg(unix)]
        return std::os::unix::fs::FileExt::write_at(self, buf, offset);
        #[cfg(windows)]
        return std::os::windows::fs::FileExt::seek_write(self, buf, offset);
    }

    fn len(&mut self) -> io::Result<u64> {
        Ok(self.metadata()?.len())
    }
}
